"use client";

import React from "react";
import { useRouter } from "next/navigation";
import { ArrowLeft } from "lucide-react";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";

interface DetailLayoutProps {
    backLink: {
        label: string;
        href?: string;
    };
    title: string;
    subtitle?: string;
    actions?: React.ReactNode;
    children: React.ReactNode;
}

export function DetailLayout({
    backLink,
    title,
    subtitle,
    actions,
    children,
}: DetailLayoutProps) {
    const router = useRouter();

    const handleBack = () => {
        if (backLink.href) {
            router.push(backLink.href);
        } else {
            router.back();
        }
    };

    return (
        <div className="w-full h-full flex flex-col bg-slate-50 overflow-hidden">
            {/* Standardized Header */}
            <div className="flex items-center justify-between px-6 md:px-8 py-5 shrink-0 bg-white border-b shadow-sm z-20">
                <div className="flex items-center gap-4">
                    <Button
                        variant="ghost"
                        size="icon"
                        onClick={handleBack}
                        className="h-10 w-10 rounded-full hover:bg-primary hover:text-white text-slate-500 border border-slate-200 shadow-sm transition-all"
                    >
                        <ArrowLeft className="h-5 w-5" />
                    </Button>
                    <div>
                        <h1 className="text-xl font-bold text-slate-900">{title}</h1>
                        {subtitle && (
                            <p className="text-sm font-medium text-slate-500">
                                {subtitle}
                            </p>
                        )}
                    </div>
                </div>
                <div className="flex items-center gap-3">
                    {actions}
                </div>
            </div>

            {/* Content Area */}
            <div className="flex-1 overflow-y-auto">
                <div className="w-full max-w-[1600px] mx-auto p-6 md:p-8 pb-32 space-y-8">
                    {children}
                </div>
            </div>
        </div>
    );
}

interface DetailSectionProps {
    title: string;
    children: React.ReactNode;
    className?: string;
}

export function DetailSection({ title, children, className }: DetailSectionProps) {
    return (
        <div className={cn("space-y-4", className)}>
            <h2 className="text-lg font-bold text-slate-900 flex items-center gap-2">
                <div className="w-1 h-6 bg-primary rounded-full" />
                {title}
            </h2>
            <div className="bg-white rounded-3xl border shadow-sm p-8">
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-y-8 gap-x-12">
                    {children}
                </div>
            </div>
        </div>
    );
}

interface DetailItemProps {
    label: string;
    value: React.ReactNode;
    className?: string;
}

export function DetailItem({ label, value, className }: DetailItemProps) {
    return (
        <div className={cn("space-y-2", className)}>
            <p className="text-xs font-semibold text-slate-500 uppercase tracking-wide">
                {label}
            </p>
            <div className="text-base font-bold text-slate-900 border border-slate-100 rounded-xl px-4 py-3 bg-slate-50 min-h-[48px] flex items-center break-words">
                {value || "—"}
            </div>
        </div>
    );
}
